#!/usr/bin/env node
/** Bundle src/i18n/*.json → src/i18n/locales.js for offline load in Tauri webview. */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const i18nDir = path.join(root, 'src', 'i18n');
const locales = {};

for (const code of ['en', 'it', 'es', 'fr', 'de']) {
  const file = path.join(i18nDir, `${code}.json`);
  locales[code] = JSON.parse(fs.readFileSync(file, 'utf8'));
}

const out = `/* Generated by scripts/build-i18n-bundle.mjs — do not edit by hand */\nwindow.MUSOMO_LOCALES = ${JSON.stringify(locales, null, 2)};\n`;
fs.writeFileSync(path.join(i18nDir, 'locales.js'), out);
console.log('Wrote src/i18n/locales.js', Object.keys(locales).map(c => `${c}:${Object.keys(locales[c]).length}`).join(', '));
